import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int ia = sc.nextInt();
        int ib = sc.nextInt();
        int fa = sc.nextInt();
        int fb = sc.nextInt();

        // Diferenças necessárias em cada lâmpada (XOR indica se precisa trocar de estado)
        int da = fa ^ ia;
        int db = fb ^ ib;

        // Sejam x = apertos em C1 e y = apertos em C2:
        //   Lâmpada B muda com y -> y mod 2 = db, logo custo mínimo de y é db (0 ou 1)
        //   Lâmpada A muda com x ou y -> x mod 2 = da ^ db, logo custo mínimo de x é da ^ db
        // Como apenas a paridade importa e cada aperto custa 1, o mínimo é x + y com x, y ∈ {0, 1}.
        int y = db;
        int x = da ^ db;

        System.out.println(x + y);
    }
}
